import { test } from "node:test";
import assert from "node:assert/strict";
import { createHmac } from "node:crypto";
import { loadConfig } from "../src/gateway/config.ts";
import { redact } from "../src/gateway/redact.ts";
import { diagnosticsReport, startupLogLine } from "../src/gateway/diagnostics.ts";
import { buildUplinkRequest, verifyFirmwareManifest } from "../src/gateway/cloud.ts";

const SECRETS = {
    MQTT_PASSWORD: "mqtt-pw-7f3a",
    CLOUD_API_KEY: "ck_live_91b2c4",
    OTA_SIGNING_SECRET: "ota-sign-55e1",
    WEBHOOK_TOKEN: "hook-tok-0c9d",
};

const env = {
    SITE_ID: "plant-12",
    MQTT_URL: "mqtts://gw12:mqtt-pw-7f3a@broker.example.com:8883",
    MQTT_USERNAME: "gw12",
    MQTT_PASSWORD: SECRETS.MQTT_PASSWORD,
    CLOUD_ENDPOINT: "https://ingest.example.com",
    CLOUD_API_KEY: SECRETS.CLOUD_API_KEY,
    OTA_SIGNING_SECRET: SECRETS.OTA_SIGNING_SECRET,
    ALERT_WEBHOOKS: JSON.stringify([{ url: "https://hooks.example.com/alerts", authToken: SECRETS.WEBHOOK_TOKEN }]),
};

const leaked = (text: string) => Object.entries(SECRETS).filter(([, v]) => text.includes(v)).map(([k]) => k);

test("config is read from the environment and missing settings are rejected", () => {
    const config = loadConfig(env);
    assert.equal(config.siteId, "plant-12");
    assert.equal(config.ota.channel, "stable");
    assert.equal(config.alertWebhooks.length, 1);
    assert.throws(() => loadConfig({ ...env, CLOUD_API_KEY: " " }), /CLOUD_API_KEY/);
});

test("the diagnostics page still shows the non-secret settings", () => {
    const report = diagnosticsReport(loadConfig(env), new Date("2026-11-19T08:00:00Z"), new Date("2026-11-19T09:30:00Z"), 42);
    const config = report.config as Record<string, any>;
    assert.equal(report.uptimeSeconds, 5400);
    assert.equal(config.siteId, "plant-12");
    assert.equal(config.cloud.endpoint, "https://ingest.example.com");
    assert.equal(config.mqtt.username, "gw12");
    assert.equal(config.alertWebhooks[0].url, "https://hooks.example.com/alerts");
});

test("the diagnostics page contains none of the credentials", () => {
    const report = JSON.stringify(diagnosticsReport(loadConfig(env), new Date(0), new Date(0), 0));
    console.log("secrets visible on /debug/status:", leaked(report));
    assert.deepEqual(leaked(report), []);
});

test("the startup log line doesn't carry the cloud API key or OTA signing secret", () => {
    const line = startupLogLine(loadConfig(env), "4.2.0");
    const config = JSON.parse(line).config;
    assert.equal(config.cloud.apiKey, "[redacted]");
    assert.equal(config.ota.signingSecret, "[redacted]");
});

test("a password inside the broker URL is masked", () => {
    const shown = redact(loadConfig(env)) as Record<string, any>;
    assert.equal(shown.mqtt.url, "mqtts://gw12:***@broker.example.com:8883");
    assert.equal(shown.mqtt.password, "[redacted]");
});

test("redaction works on any field name style and leaves other values alone", () => {
    const shown = redact({ DB_PASSWORD: "p", stripeKey: "k", sessionToken: "t", keyId: "kid-1", retries: 3, tags: ["a"] });
    assert.deepEqual(shown, { DB_PASSWORD: "[redacted]", stripeKey: "[redacted]", sessionToken: "[redacted]", keyId: "kid-1", retries: 3, tags: ["a"] });
});

test("redacting for display doesn't change the live config the gateway uses", () => {
    const config = loadConfig(env);
    diagnosticsReport(config, new Date(0), new Date(0), 0);
    const req = buildUplinkRequest(config, [{ sensorId: "t1", at: "2026-11-19T09:00:00Z", value: 21.5 }]);
    assert.equal(req.headers.authorization, `Bearer ${SECRETS.CLOUD_API_KEY}`);
    assert.equal(req.url, "https://ingest.example.com/v1/sites/plant-12/readings");
    const manifest = '{"version":"4.3.0"}';
    const sig = createHmac("sha256", SECRETS.OTA_SIGNING_SECRET).update(manifest).digest("hex");
    assert.equal(verifyFirmwareManifest(config, manifest, sig), true);
    assert.equal(verifyFirmwareManifest(config, manifest.replace("4.3.0", "4.3.1"), sig), false);
});
